-- Source-proven CORUM 2026 notice terms: precise entry fee, minimum one part,
-- first day of the sixth month following subscription (do not promise an exact date).
ALTER TABLE maximus_agents.scpi_candidate_regulatory_metric_evidence
 ALTER COLUMN numeric_value TYPE numeric(12,4);
ALTER TABLE maximus_agents.scpi_candidate_regulatory_metric_evidence
 DROP CONSTRAINT IF EXISTS scpi_candidate_regulatory_metric_evidence_metric_check;
ALTER TABLE maximus_agents.scpi_candidate_regulatory_metric_evidence
 ADD CONSTRAINT scpi_candidate_regulatory_metric_evidence_metric_check
 CHECK(metric IN('risk_sri','recommended_holding_years',
 'subscription_fees_pct','minimum_initial_parts','enjoyment_wait_months'));
ALTER TABLE maximus_agents.scpi_candidate_regulatory_metric_evidence
 DROP CONSTRAINT IF EXISTS scpi_candidate_regulatory_metric_evidence_document_kind_check;
ALTER TABLE maximus_agents.scpi_candidate_regulatory_metric_evidence
 ADD CONSTRAINT scpi_candidate_regulatory_metric_evidence_document_kind_check
 CHECK(document_kind IN('dic','note'));
