INSERT INTO maximus_agents.scpi_candidate_regulatory_metric_evidence
 (scpi_slug,metric,numeric_value,unit,document_kind,source_url,source_sha256,source_page,evidence_text)
SELECT t.slug,t.metric,t.amount::numeric,t.unit,'note',t.url,t.sha,t.pageno::integer,t.excerpt
FROM terms t JOIN maximus_agents.scpi_candidate_regulatory_documents d
 ON d.scpi_slug=t.slug AND d.document_kind='note'
 AND d.source_url=t.url AND d.pdf_sha256=t.sha
WHERE d.identity_verified AND d.kind_verified
ON CONFLICT (scpi_slug,metric) DO NOTHING;
